local config = {
  ui_story_30040601_1_dialog_content = "Hey buddy, got some spare time today?",
  ui_story_30040601_2_dialog_content = "Er... What's the matter?",
  ui_story_30040601_3_dialog_content = "Just a little favor, is all! We're short one person for a job, and we could use your help!",
  ui_story_30040601_4_dialog_content = "It's just a small job...",
  ui_story_30040601_5_dialog_content = "Considering your line of work, am I really the right person to ask?",
  ui_story_30040601_6_dialog_content = "I'm not much of a fighter, especially when it comes to the way you two fight...",
  ui_story_30040601_7_dialog_content = "Aw, relax! You won't need to do any fighting!",
  ui_story_30040601_8_dialog_content = "But...",
  ui_story_30040601_9_dialog_content = "You worry too much, bro! Just come with us!",
  ui_story_30040601_10_dialog_content = "Come on, bro!",
  ui_story_30040601_11_dialog_content = "Sigh, okay.",
  ui_story_30040601_12_dialog_content = "Let's go!",
  ui_story_30040601_13_dialog_content = "Y-You don't need to drag me away, guys. I promise I won't run...",
  ui_story_30040601_14_dialog_content = "It feels like I'm being kidnapped...",
  ui_story_30040601_15_dialog_content = "We're here, let's get ready for business!",
  ui_story_30040601_16_dialog_content = "Where are we, guys?",
  ui_story_30040601_17_dialog_content = "This is the place where the Guild houses its prisoners. We're here to take someone out.",
  ui_story_30040601_18_dialog_content = "What?! I-I want nothing to do with such a horrible thing!",
  ui_story_30040601_19_dialog_content = "There you go worrying again, bro! It would be much easier if that's the case.",
  ui_story_30040601_20_dialog_content = "Now come here and help me put these handcuffs on Kuma.",
  ui_story_30040601_21_dialog_content = "Be gentle...",
  ui_story_30040601_22_dialog_content = "H-Handcuffs? Is Kuma getting imprisoned?!",
  ui_story_30040601_23_dialog_content = "Nope! Kuma's just pretending to be a certain prisoner, that's all!",
  ui_story_30040601_24_dialog_content = "The guy in question cut a deal with one of the Guild's higher-ups. From what we know, he's already been released and given a new identity.",
  ui_story_30040601_25_dialog_content = "Our job is to put on a good show for everyone—",
  ui_story_30040601_26_dialog_content = "—and make sure everyone sees the criminal, a.k.a. Kuma, die an accidental death!",
  ui_story_30040601_27_dialog_content = "That's when I, Master Detective Pengy, will arrive at the scene. With the help of my trusty assistant, that would be you, we'll confirm the prisoner's death beyond any reasonable doubt!",
  ui_story_30040601_28_dialog_content = "Y-You even prepared costumes for this?!",
  ui_story_30040601_29_dialog_content = "After that, my trusty assistant, again, that's you, will load the corpse into our car, and the three of us will drive off into the sunset. The end!",
  ui_story_30040601_30_dialog_content = "Bravo! Bravo!",
  ui_story_30040601_31_dialog_content = "Thank you, thank you! You're much too kind!",
  ui_story_30040601_32_dialog_content = "Wait a second, if the Guild's higher-ups already agreed to let him go, then what's the point of this whole act?",
  ui_story_30040601_33_dialog_content = "Oh, my sweet, summer child! The Guild's chock-full of different parties with conflicting interests. Sometimes they duke it out in the open, other times they do things on the down-low...",
  ui_story_30040601_34_dialog_content = "The higher-up in question can't actually let this prisoner go, so he arranged this fake-death drama instead!",
  ui_story_30040601_35_dialog_content = "And you're sure it's okay to do this...?",
  ui_story_30040601_36_dialog_content = "Of course! After all, this is a job straight from the Guild's top brass!",
  ui_story_30040601_37_dialog_content = "Our usual jobs have been pretty scarce lately. It feels like more and more people are starting to play nice together, which puts most of our skills out of work.",
  ui_story_30040601_38_dialog_content = "But with my brains and brilliant acting skills, this Master Detective bit should bring in the big bucks!",
  ui_story_30040601_39_dialog_content = "My role's important too...",
  ui_story_30040601_40_dialog_content = "Of course it is, buddy! Nothing like a convincing corpse to really tie it all together, right? Heck, we might even make it into the movies, if we play our cards right!",
  ui_story_30040601_41_dialog_content = "Yeah! Movies! Swimming pool!",
  ui_story_30040601_42_dialog_content = "Swimming pool? What does that have to do with movies?",
  ui_story_30040601_43_dialog_content = "Everyone ready? Let the show—",
  ui_story_30040601_44_dialog_content = "<size=45>Begin!</size>",
  ui_story_30040601_45_dialog_content = "...",
  ui_story_30040601_46_dialog_content = "...",
  ui_story_30040601_47_dialog_content = "...",
  ui_story_30040601_48_dialog_content = "Quit standing around, Kuma! You're supposed to play dead! Quick, PlayerName, shout out that there's a dead person over here!",
  ui_story_30040601_49_dialog_content = "Uh, oh no! <size=45>There's a dead person over here! Help, everyone!</size>",
  ui_story_30040601_50_dialog_content = "Hey, hey! What's with all the commotion?!",
  ui_story_30040601_51_dialog_content = "Yikes! Someone's lying in a pool of blood over here—",
  ui_story_30040601_52_dialog_content = "I-It's one of our prisoners! He's wearing one of our uniforms and everything!",
  ui_story_30040601_53_dialog_content = "But what's he doing out here? Just what's going on?!",
  ui_story_30040601_54_dialog_content = "He's not breathing! Is the prisoner dead?!",
  ui_story_30040601_55_dialog_content = "This looks like a job for <size=45>Master Detective Pengy</size>! Step aside!",
  ui_story_30040601_56_dialog_content = "And just who the heck are you?",
  ui_story_30040601_57_dialog_content = "Oh, just a famous detective passing through. As for this bold-looking fellow here, he's my assistant.",
  ui_story_30040601_58_dialog_content = "As you can see, my assistant and I have just arrived, clearing our names of any suspicion.",
  ui_story_30040601_59_dialog_content = "You're joking, right? I'm gonna need to see some identification from both of you right now.",
  ui_story_30040601_60_dialog_content = "What's this? But how could you suspect us when I just told you I'm a famous detective?! The detective's never on the list of suspects!",
  ui_story_30040601_61_dialog_content = "Um, sir? Don't you think we should investigate the victim's cause of death first?",
  ui_story_30040601_62_dialog_content = "Ah, you made a point, assistant. Now let's take a look at that corpse.",
  ui_story_30040601_63_dialog_content = "Ahem! I, Master Detective Pengy, will now begin my investigation into the matter!",
  ui_story_30040601_64_dialog_content = "To start, I would like to ask some questions—",
  ui_story_30040601_65_dialog_content = "About time too! Heck, I feel more inclined to believe you're a detective now!",
  ui_story_30040601_66_dialog_content = "Can you confirm whether or not this is one of your prisoners?",
  ui_story_30040601_67_dialog_content = "I can, and he is. He's wearing one of our uniforms, see? It has his prisoner number and everything.",
  ui_story_30040601_68_dialog_content = "And what has he done today while in custody?",
  ui_story_30040601_69_dialog_content = "Let's take a look at the records...",
  ui_story_30040601_70_dialog_content = "My superiors took him away for questioning this morning. About an hour ago, they called and said they were finished interrogating him, and that someone would escort him back.",
  ui_story_30040601_71_dialog_content = "He should have arrived a few minutes ago, but that's when I heard someone scream that a dead body was over here.",
  ui_story_30040601_72_dialog_content = "When I came to see, I found out that the dead person was none other than the prisoner.",
  ui_story_30040601_73_dialog_content = "I see. Were there any other witnesses?",
  ui_story_30040601_74_dialog_content = "...",
  ui_story_30040601_75_dialog_content = "...",
  ui_story_30040601_76_dialog_content = "Assistant!",
  ui_story_30040601_77_dialog_content = "Huh? Y-Yes, sir!",
  ui_story_30040601_78_dialog_content = "Did you witness anything by chance?",
  ui_story_30040601_79_dialog_content = "Err... Was I supposed to witness something?",
  ui_story_30040601_80_dialog_content = "Let me rephrase that: did you happen to witness this bear exit the vehicle, then keel over on the ground and spit up a large amount of blood?",
  ui_story_30040601_81_dialog_content = "... Yeah, that sounds about right.",
  ui_story_30040601_82_dialog_content = "When he exited the vehicle, which leg did he step out with first? His left or his right?",
  ui_story_30040601_83_dialog_content = "Ha? Is that important?",
  ui_story_30040601_84_dialog_content = "Hang on a minute! What does that have to do with his cause of death?!",
  ui_story_30040601_85_dialog_content = "Of course it's important! The cause of death is very likely linked to this crucial detail!",
  ui_story_30040601_86_dialog_content = "The wrong leg would have resulted in him losing his balance and falling down. Given his enormous size, the impact would have crushed his internal organs, leading to severe internal bleeding and death!",
  ui_story_30040601_87_dialog_content = "I see...",
  ui_story_30040601_88_dialog_content = "Internal bleeding, eh? Guess we should have a doctor and take a—",
  ui_story_30040601_89_dialog_content = "Don't touch the body! By tampering with the crime scene, you risk bringing the full weight of the law down on your own head!",
  ui_story_30040601_90_dialog_content = "Oh! S-Sorry...",
  ui_story_30040601_91_dialog_content = "Unless, of course, you were trying to cover something up?",
  ui_story_30040601_92_dialog_content = "Ha? What would I want to cover up?!",
  ui_story_30040601_93_dialog_content = "Maybe you had a grudge against the prisoner? Maybe you were just waiting for the perfect opportunity to kill him and make it look like an accident?!",
  ui_story_30040601_94_dialog_content = "(Oh, jeez... Pengy's just screaming out whatever comes to mind, isn't he? At this rate, he's really gonna make the guard mad!)",
  ui_story_30040601_95_dialog_content = "What?!?",
  ui_story_30040601_96_dialog_content = "You're the suspicious one here, pal! I've never heard of no Master Detective Pengy in my life!",
  ui_story_30040601_97_dialog_content = "Now show me your identification! I'm done screwing around with you two!",
  ui_story_30040601_98_dialog_content = "But... But...",
  ui_story_30040601_99_dialog_content = "I think we're done here, my faithful assistant! Now be a dear and load Kuma— I mean, load the corpse into the car.",
  ui_story_30040601_100_dialog_content = "Like hell! Where do you two think you're going with our prisoner?!",
  ui_story_30040601_101_dialog_content = "Urg... He's so heavy... I can't lift him at all...",
  ui_story_30040601_102_dialog_content = "Hold it! Get over here, men! These two are trying to run off with one of our prisoners!!",
  ui_story_30040601_103_dialog_content = "Crap! The bear's out of the bag!",
  ui_story_30040601_104_dialog_content = "<color=#e8d9bb>Poof—</color>",
  ui_story_30040601_105_dialog_content = "Kuma, PlayerName, get in the car! We're getting out of here!",
  ui_story_30040601_106_dialog_content = "Snore...",
  ui_story_30040601_107_dialog_content = "Hey! Wake up, you big, hairy lump!",
  ui_story_30040601_108_dialog_content = "O-Okay!",
  ui_story_30040601_109_dialog_content = "What do we do now? The guards are gaining on us!",
  ui_story_30040601_110_dialog_content = "Relax! With my driving skills, we'll shake off those losers in no time!",
  ui_story_30040601_111_dialog_content = "Wooo! Excitement!",
  ui_story_30040601_112_dialog_content = "Bwahahaha! Good riddance, I was starting to get bored of playing detective!",
  ui_story_30040601_113_dialog_content = "You sure about that? It looked like you were having a great time!",
  ui_story_30040601_114_dialog_content = "Sure, but nothing beats a good, old-fashioned highway chase!",
  ui_story_30040601_115_dialog_content = "This is right up our alley!",
  ui_story_30040601_116_dialog_content = "Isn't that right, partner? Woohoo!",
  ui_story_30040601_117_dialog_content = "High-five! Woohoo!",
  ui_story_30040601_118_dialog_content = "D-Don't high-five each other! Keep your hands on the steering wheel!!",
  ui_story_30040601_119_dialog_content = "Strap in, kid! It's time to put the pedal to the metal!",
  ui_story_30040601_120_dialog_content = "Stop! There's a <size=50>cliff</size> up ahead!!",
  ui_story_30040601_121_dialog_content = "Hey! Didn't you hear me?! I said there's a <size=50>cliff</size> up ahead!!!",
  ui_story_30040601_122_dialog_content = "Yohoooo! This ain't the time for chickening out, buddy!",
  ui_story_30040601_123_dialog_content = "Turning around or stopping now would only make us cowards! Even slowing down would be unforgivable!",
  ui_story_30040601_124_dialog_content = "All we can do now is charge forward like wild animals and let fate take the wheel!",
  ui_story_30040601_125_dialog_content = "Ready to meet your maker, Caelestite?",
  ui_story_30040601_126_dialog_content = "Charge—",
  ui_story_30040601_127_dialog_content = "I-I'm not ready at all! Stop the car!",
  ui_story_30040601_128_dialog_content = "Weeee! We're flying high now, boys!",
  ui_story_30040601_129_dialog_content = "Flying... like a cloud...",
  ui_story_30040601_130_dialog_content = "<size=50>Aaaaaaaaahhhhh—</size>",
  ui_story_30040601_131_dialog_content = "A gentle breeze whispering in my ear, and fluffy clouds floating all around us. It would be perfect if not for the Caelestite's constant screaming!",
  ui_story_30040601_132_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_30040601_133_dialog_content = "Glub, glub, glub... Help... Glub, glub, glub...",
  ui_story_30040601_134_dialog_content = "Hey! Wake up, buddy!",
  ui_story_30040601_135_dialog_content = "Cough, cough, cough!",
  ui_story_30040601_136_dialog_content = "A-Am I in heaven?",
  ui_story_30040601_137_dialog_content = "You're darn right we're in heaven!",
  ui_story_30040601_138_dialog_content = "\"I should never have listened to you guys.\" That's what I want to be engraved on my tombstone!",
  ui_story_30040601_139_dialog_content = "Your tombstone?",
  ui_story_30040601_140_dialog_content = "No, that won't do. I need something cooler than that.",
  ui_story_30040601_141_dialog_content = "\"Here lies the world's greatest Caelestite!\"",
  ui_story_30040601_142_dialog_content = "\"Only fools have regrets, and I was no fool!\"",
  ui_story_30040601_143_dialog_content = "\"There will never be another genius like me!\"",
  ui_story_30040601_144_dialog_content = "Caelestite... H-Hurry...",
  ui_story_30040601_145_dialog_content = "Argh, this is a tough one! What should my epitaph say?!",
  ui_story_30040601_146_dialog_content = "Something tough!",
  ui_story_30040601_147_dialog_content = "I guess a tough-sounding epitaph suits me best.",
  ui_story_30040601_148_dialog_content = "Something cool!",
  ui_story_30040601_149_dialog_content = "Yeah, something cool and detached is just my style!",
  ui_story_30040601_150_dialog_content = "Oh, I just remembered I left some cake in the fridge yesterday! I didn't want to eat it all in one sitting, so I saved it for later...",
  ui_story_30040601_151_dialog_content = "Hey! I said wake up, partner!",
  ui_story_30040601_152_dialog_content = "Huh? We're... We're not dead?!",
  ui_story_30040601_153_dialog_content = "The Gold River...",
  ui_story_30040601_154_dialog_content = "Wait, so the Gold River was at the bottom of that cliff?! We landed in the river!",
  ui_story_30040601_155_dialog_content = "Yep, and Kuma dragged you back to shore! Guess you must've swallowed a lot of water, to be talking all that nonsense just now.",
  ui_story_30040601_156_dialog_content = "So... Does that mean we can finally...",
  ui_story_30040601_157_dialog_content = "Go home? Yep!",
  ui_story_30040601_158_dialog_content = "So hot... Need my fridge...",
  ui_story_30040601_159_dialog_content = "But what about the guys who were chasing us?",
  ui_story_30040601_160_dialog_content = "The car's already sitting at the bottom of the river. Even if they find the wreckage, they'll just assume we drowned and our bodies floated away!",
  ui_story_30040601_161_dialog_content = "And dead men tell no tales! Mission accomplished!",
  ui_story_30040601_162_dialog_content = "Do you really think they're not gonna look into this bird-brained scheme of yours?",
  ui_story_30040601_163_dialog_content = "Hey, watch it! Besides, that's the Guild's business, not ours.",
  ui_story_30040601_164_dialog_content = "As far as the Polar Partners are concerned, this was just another job well done! That's why you can count on us to tackle any task!",
  ui_story_30040601_165_dialog_content = "Thanks for the reminder. I'll be sure never to hire you guys for anything..."
}
return config
